using Azurite.NormalEditor.Entry;
using Azurite.NormalEditor.Adapter;
using System.Text.Json;

if(args.Length==3&&args[0]=="--metadata")return ShutdownHostMetadataChecks.Run(args[1],args[2]);
if(args.Length!=1)throw new ArgumentException("Supply a fresh C-only fixture output directory.");
string output=Path.GetFullPath(args[0]);
if(!output.StartsWith("C:\\",StringComparison.OrdinalIgnoreCase)||Directory.Exists(output))throw new ArgumentException("Fresh C-only fixture output required.");
Directory.CreateDirectory(output);
var checks=new List<object>();
void Need(bool value,string reason){if(!value)throw new Exception(reason);}
void Test(string name,Action action){try{action();checks.Add(new{name,passed=true,error=(string?)null});}catch(Exception error){checks.Add(new{name,passed=false,error=error.Message});}}
void Denied(ShutdownFixture f){Need(!f.Close(),"close admitted");Need(!f.Shutdown.Closed && f.CloseCalls==0,"failed precheck invoked adapter or advertised closed");}
Fixture AdapterFixture(){var f=new Fixture(output);f.Admission.BeforeRoute=null;f.Admission.Revoked=false;f.Native.AfterWrite=null;return f;}

Test("complete quiescent normal shutdown stops producer then closes actual adapter once",()=>{
 var adapter=AdapterFixture();adapter.Start();var f=new ShutdownFixture(adapter.Binding.Policy.RunId);f.Ready();
 Need(f.Shutdown.MarkRegistered(),"registration not completed");
 Need(f.Shutdown.TryClose(()=>f.Stamp(7),()=>f.VerifyCalls++,()=>{f.CloseCalls++;Need(f.Shutdown.ProducersStopped,"adapter closed before producer stopped");return adapter.Adapter.Close();}),"healthy close rejected");
 Need(f.Shutdown.Closed&&f.Shutdown.ProducersStopped&&f.VerifyCalls==1&&f.CloseCalls==1&&adapter.Adapter.Failure is null,"close not backed by actual Core.Close");
 Need(!adapter.Adapter.Close(),"real settings policy was not closed");
});
Test("Ready alone leaves producer active and does not call close",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");Need(!f.Shutdown.Closed&&!f.Shutdown.ProducersStopped&&f.CloseCalls==0,"ready stopped observer");Need(f.Shutdown.TryEnter(f.Stamp(6),out var lease),"ready callback refused");lease!.Dispose();Need(!f.Shutdown.ProducersStopped,"callback retirement closed observer");});
Test("incomplete registration cannot invoke verification or adapter close",()=>{var f=new ShutdownFixture();f.Ready();Denied(f);Need(f.VerifyCalls==0,"unregistered close ran verifier");});
Test("registration cannot complete twice",()=>{var f=new ShutdownFixture();Need(f.Shutdown.MarkRegistered(),"first registration");Need(!f.Shutdown.MarkRegistered(),"repeat registration");Denied(f);});
Test("callback before complete registration latches refusal",()=>{var f=new ShutdownFixture();Need(!f.Shutdown.TryEnter(f.Stamp(0),out _)&&f.Gate.Failure is not null,"incomplete callback admitted");Need(!f.Shutdown.MarkRegistered(),"failed registration revived");});
Test("no natural Start or Ready cannot close",()=>{var f=new ShutdownFixture();Need(f.Shutdown.MarkRegistered(),"registration");Denied(f);});
foreach(var phase in new[]{"enter","return"})Test("pending Start "+phase+" blocks shutdown",()=>{var f=new ShutdownFixture();Need(f.Shutdown.MarkRegistered(),"registration");var token=f.Gate.StartEntered(f.Stamp(1));if(phase=="return")f.Gate.StartReturned(token,f.Stamp(2),true);Denied(f);});
foreach(var phase in new[]{"enter","return"})Test("pending Update "+phase+" blocks shutdown after ready",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");var token=f.Ticks.Enter(f.Stamp(6),200);if(phase=="return")f.Ticks.Returned(token,f.Stamp(6),200,true);Denied(f);});
Test("fully finalized Update permits a later shutdown",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");var token=f.Ticks.Enter(f.Stamp(6),200);f.Ticks.Returned(token,f.Stamp(6),200,true);Need(f.Ticks.TryComplete(token,f.Stamp(6),200,null),"Update completion");Need(f.Close()&&f.Shutdown.Closed,"finalized tick remained active");});
Test("managed host callback before external verification blocks reentrant close",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");Need(f.Shutdown.TryEnter(f.Stamp(6),out var scope),"entry");Denied(f);scope!.Dispose();Need(!f.Close(),"failed close retried");});
Test("nested host callback is refused without abandoning outer ownership",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");Need(f.Shutdown.TryEnter(f.Stamp(6),out var scope),"entry");Need(!f.Shutdown.TryEnter(f.Stamp(6),out _),"nested entry");scope!.Dispose();Denied(f);});
Test("evidence callback cannot seal while its ready record is in flight",()=>{ShutdownFixture? f=null;bool attempted=false,result=true;f=new ShutdownFixture(sink:e=>{if(e.Kind=="catalog-ready"){attempted=true;result=f!.Close();}});Need(f.Shutdown.MarkRegistered(),"registration");f.Ready();Need(attempted&&!result&&!f.Shutdown.Closed&&f.CloseCalls==0&&f.Gate.Failure is not null,"ready sink reentry closed");});
Test("deferred observation cannot close inside a native field read",()=>{var f=new ShutdownFixture();Need(f.Shutdown.MarkRegistered(),"registration");f.Start();bool close=true;f.Gate.ObserveTick(f.Stamp(5),()=>{close=f.Close();return f.Observation;},()=>f.Observation);Need(!close&&f.CloseCalls==0&&!f.Shutdown.Closed,"field-read reentry closed");});
Test("idle guard callback cannot close while readiness is unresolved",()=>{var f=new ShutdownFixture();Need(f.Shutdown.MarkRegistered(),"registration");f.Start();bool close=true;f.Gate.Tick(f.Observation,()=>{close=f.Close();return f.Observation;});Need(!close&&f.CloseCalls==0&&!f.Shutdown.Closed,"guard reentry closed");});
Test("registration verifier reentry cannot be swallowed into success",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");var result=f.Shutdown.TryClose(()=>f.Stamp(7),()=>{Need(!f.Close(),"nested close");},()=>{f.CloseCalls++;return true;});Need(!result&&!f.Shutdown.Closed&&f.CloseCalls==0,"swallowed verifier reentry closed");});
Test("callback during close verification fails before producer stop and adapter close",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");var result=f.Shutdown.TryClose(()=>f.Stamp(7),()=>{Need(!f.Shutdown.TryEnter(f.Stamp(7),out _),"callback during close");},()=>{f.CloseCalls++;return true;});Need(!result&&!f.Shutdown.ProducersStopped&&f.CloseCalls==0,"failed verification closed");});
Test("adapter-close reentry cannot return a false successful close",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");var result=f.Shutdown.TryClose(()=>f.Stamp(7),()=>{},()=>{Need(!f.Close(),"nested adapter close");return true;});Need(!result&&!f.Shutdown.Closed&&f.Shutdown.ProducersStopped,"nested close accepted");});
Test("exception from verification retains failure without invoking adapter",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");Need(!f.Shutdown.TryClose(()=>f.Stamp(7),()=>throw new Exception("lease revoked"),()=>{f.CloseCalls++;return true;}),"revoked verifier");Need(f.Gate.Failure!.Contains("lease revoked")&&f.CloseCalls==0&&!f.Shutdown.Closed,"verification failure lost");});
foreach(var throwing in new[]{false,true})Test("adapter "+(throwing?"throw":"false")+" never authorizes Seal",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");int seals=0;bool result=f.Shutdown.TryClose(()=>f.Stamp(7),()=>{},()=>throwing?throw new Exception("adapter-failed"):false);if(result)seals++;Need(seals==0&&!f.Shutdown.Closed&&f.Shutdown.ProducersStopped&&f.Gate.Failure is not null,"adapter failure allowed seal");Need(!f.Close(),"failed close retried");});
Test("actual AdapterCoordinator with pending native finalizer refuses close",()=>{var adapter=AdapterFixture();adapter.BeforeYield();var f=new ShutdownFixture(adapter.Binding.Policy.RunId);f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");Need(!f.Shutdown.TryClose(()=>f.Stamp(7),()=>{},adapter.Adapter.Close),"active real adapter accepted");Need(!f.Shutdown.Closed&&adapter.Adapter.Failure is not null&&adapter.Fatal.Calls>0,"false closure of actual active coordinator");});
foreach(var field in new[]{"run","process","managed","native"})Test("shutdown rejects foreign "+field+" identity",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");var s=f.Stamp(7);s=field switch{"run"=>s with{RunId=Guid.NewGuid().ToString("D")},"process"=>s with{ProcessId=s.ProcessId+1},"managed"=>s with{ManagedThreadId=s.ManagedThreadId+1},_=>s with{NativeThreadId=99}};Need(!f.Shutdown.TryClose(()=>s,()=>f.VerifyCalls++,()=>{f.CloseCalls++;return true;})&&f.VerifyCalls==0&&f.CloseCalls==0&&!f.Shutdown.Closed,"foreign close accepted");});
Test("forged matching stamp on another actual managed thread is refused",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");var s=f.Stamp(7);bool closed=Task.Run(()=>f.Shutdown.TryClose(()=>s,()=>f.VerifyCalls++,()=>{f.CloseCalls++;return true;})).GetAwaiter().GetResult();Need(!closed&&f.CloseCalls==0&&!f.Shutdown.Closed,"actual foreign thread accepted");});
Test("foreign close cannot wait on an owner-held evidence lock",()=>{ShutdownFixture? f=null;Task<bool>? request=null;bool returned=false;f=new ShutdownFixture(sink:e=>{if(e.Kind=="catalog-ready"){request=Task.Run(()=>f!.Close());returned=request.Wait(TimeSpan.FromSeconds(1));}});Need(f.Shutdown.MarkRegistered(),"registration");f.Ready();Need(request is not null&&!request.GetAwaiter().GetResult(),"foreign close accepted");Need(returned&&f.CloseCalls==0,"foreign close waited for the owner evidence callback to return");});
Test("post-ready normal shutdown may occur after readiness deadline",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");Need(f.Shutdown.TryClose(()=>f.Stamp(1000),()=>{},()=>true)&&f.Shutdown.Closed,"readiness deadline incorrectly became shutdown deadline");});
Test("close clock reversal rejects before adapter",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");Need(!f.Shutdown.TryClose(()=>f.Stamp(1),()=>{},()=>{f.CloseCalls++;return true;})&&f.CloseCalls==0,"reverse close clock");});
Test("clock exception does not resample or allow close",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");int samples=0;Need(!f.Shutdown.TryClose(()=>{samples++;throw new Exception("bad clock");},()=>{},()=>{f.CloseCalls++;return true;})&&samples==1&&f.CloseCalls==0&&!f.Shutdown.Closed,"clock failure hidden/resampled");});
Test("prior observer failure cannot be closed into a successful terminal",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");f.Gate.Reject("original failure",f.Stamp(6));Denied(f);Need(f.Gate.Failure=="original failure","primary failure overwritten");});
Test("late Catalog callbacks after explicit close produce no reads or evidence",()=>{var f=new ShutdownFixture();f.Ready();Need(f.Shutdown.MarkRegistered(),"registration");Need(f.Close(),"close");int records=f.Events.Count,reads=0;for(int i=0;i<3;i++){if(f.Shutdown.TryEnter(f.Stamp(9),out var scope)){using(scope)reads++;}}Need(reads==0&&f.Events.Count==records&&f.Shutdown.Closed,"closed producer emitted or revived");Need(!f.Close()&&f.CloseCalls==1&&f.Events.Count==records,"duplicate close invoked source or poisoned completed producer");});
Test("writer failure during close refusal cannot manufacture closed",()=>{var f=new ShutdownFixture(sink:e=>{if(e.Kind=="catalog-failed")throw new IOException("writer down");});f.Ready();Denied(f);Need(!f.Shutdown.Closed&&f.Gate.Failure is not null,"failed writer manufactured terminal");});
ForeignCallbackChecks.Run(Test,Need);

Console.WriteLine(JsonSerializer.Serialize(checks));int failed=checks.Count(x=>!(bool)x.GetType().GetProperty("passed")!.GetValue(x)!);
Console.WriteLine($"RESULT passed={checks.Count-failed} failed={failed}; nativeExecuted=false; hostExecuted=false; fixtureOnly=true");return failed==0?0:1;

sealed class ShutdownFixture
{
 internal readonly List<CatalogEvidence> Events=new();internal readonly CatalogBinding Binding;internal readonly CatalogReadiness Gate;internal readonly CatalogTickCallbacks Ticks;internal readonly CatalogShutdown Shutdown;
 internal int VerifyCalls,CloseCalls;
 internal ShutdownFixture(string? id=null,Action<CatalogEvidence>? sink=null){Binding=new(id??Guid.NewGuid().ToString("D"),Environment.ProcessId,Environment.CurrentManagedThreadId,7,100);Gate=new(Binding,e=>{Events.Add(e);sink?.Invoke(e);});Ticks=new(Gate);Shutdown=new(Gate,Ticks);}
 internal CatalogStamp Stamp(long milliseconds)=>new(Binding.RunId,Binding.ProcessId,Binding.ManagedThreadId,Binding.NativeThreadId,milliseconds,milliseconds,100);
 internal CatalogObservation Observation=>new(Stamp(5),200,300,400,"CatalogScene",false,false,true,true,false,0,0,false);
 internal void Start(){var token=Gate.StartEntered(Stamp(1));Gate.StartReturned(token,Stamp(2),true);Gate.StartFinalized(token,Stamp(3),null);}
 internal void Ready(){Start();Gate.Tick(Observation,()=>Observation);}
 internal bool Close()=>Shutdown.TryClose(()=>Stamp(7),()=>VerifyCalls++,()=>{CloseCalls++;return true;});
}
